{"code": "import pandas as pd, numpy as np, statsmodels.api as sm
df = pd.read_csv('data/explore.csv')
cands = ['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
d = df.dropna(subset=['tensile_mpa']).copy()
print("Per-lab slopes (simple regression within lab):")
for c in cands:
    row=[]
    for lab,g in d.dropna(subset=[c]).groupby('lab'):
        if len(g)>5:
            b=np.polyfit(g[c],g['tensile_mpa'],1)[0]
            row.append(f"{lab}:{b:+.3f}")
    print(f"{c:14s} "+"  ".join(row))
"}
